import React, {useMemo, useState} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import {
  Check,
  ChevronDown,
  ChevronRight,
  ChevronUp,
  ChevronsUpDown,
  X,
} from "lucide-react";
import {cn} from "@/lib/utils";
import {Badge} from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type {
  DataTableColumn,
  DataTableEvents,
  DataTableProps,
  DataTableRow as DataTableRowType,
} from "./dataTable.types";

// ---------------------------------------------------------------------------
// Cell renderer
// ---------------------------------------------------------------------------

function renderCell(
  column: DataTableColumn,
  value: unknown,
  parentCard: string,
): React.ReactNode {
  if (value == null) return null;

  switch (column.type) {
    case "number": {
      const num = typeof value === "number" ? value : Number(value);
      return isNaN(num)
        ? String(value)
        : column.format
          ? column.format(num)
          : String(num);
    }

    case "date": {
      if (column.format) {
        return column.format(value as Date | string);
      }
      const d = value instanceof Date ? value : new Date(String(value));
      return isNaN(d.getTime()) ? String(value) : d.toLocaleDateString();
    }

    case "badge": {
      const strVal = String(value);
      const variant = column.variants?.[strVal] ?? "secondary";
      return <Badge variant={variant}>{strVal}</Badge>;
    }

    case "boolean": {
      return value ? (
        <Check className="size-4 text-green-600" aria-label="true" />
      ) : (
        <X className="size-4 text-muted-foreground" aria-label="false" />
      );
    }

    case "card": {
      // Cell value is expected to be a PiCardRef (string)
      return <Card cardName={String(value)} parentCard={parentCard} />;
    }

    default:
      // "text" or omitted type
      return String(value);
  }
}

// ---------------------------------------------------------------------------
// Sort icon
// ---------------------------------------------------------------------------

function SortIcon({
  columnKey,
  activeKey,
  ascending,
}: {
  columnKey: string;
  activeKey: string | undefined;
  ascending: boolean;
}): React.ReactNode {
  if (columnKey !== activeKey) {
    return <ChevronsUpDown className="ml-1 inline size-3.5 opacity-40" />;
  }
  return ascending ? (
    <ChevronUp className="ml-1 inline size-3.5" />
  ) : (
    <ChevronDown className="ml-1 inline size-3.5" />
  );
}

// ---------------------------------------------------------------------------
// Pagination controls
// ---------------------------------------------------------------------------

function PaginationBar({
  page,
  totalPages,
  onPrev,
  onNext,
}: {
  page: number;
  totalPages: number;
  onPrev: () => void;
  onNext: () => void;
}): React.ReactNode {
  return (
    <div className="flex items-center justify-end gap-2 mt-2 px-2">
      <span className="text-sm text-muted-foreground">
        Page {page + 1} of {totalPages}
      </span>
      <button
        type="button"
        className={cn(
          "rounded border px-2 py-1 text-sm transition-colors",
          "hover:bg-accent disabled:cursor-not-allowed disabled:opacity-40",
        )}
        disabled={page === 0}
        onClick={onPrev}
      >
        Previous
      </button>
      <button
        type="button"
        className={cn(
          "rounded border px-2 py-1 text-sm transition-colors",
          "hover:bg-accent disabled:cursor-not-allowed disabled:opacity-40",
        )}
        disabled={page >= totalPages - 1}
        onClick={onNext}
      >
        Next
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Helper: derive a human-readable title from a camelCase key
// ---------------------------------------------------------------------------

function keyToTitle(key: string): string {
  return key
    .replace(/([A-Z])/g, " $1")
    .replace(/^./, (s) => s.toUpperCase())
    .trim();
}

// ---------------------------------------------------------------------------
// Main data-table component
// ---------------------------------------------------------------------------

export const DataTableComponent = (
  props: PiCardProps<DataTableProps, DataTableEvents>,
): React.ReactNode => {
  const {
    columns,
    rows,
    caption,
    sortKey: sortKeyProp,
    sortAscending: sortAscendingProp,
    pageSize,
    currentPage: currentPageProp,
    stickyHeader = false,
    striped = false,
    hoverable = true,
    compact = false,
    emptyCard,
    emptyText = "No data",
    className,
    cardName,
    onRowClicked,
    onSortChanged,
    onShowDetail,
    onHideDetail,
    onPageChanged,
  } = props;

  // ── Expanded-rows state ──────────────────────────────────────────────────
  const [expandedRows, setExpandedRows] = useState<Set<string | number>>(
    new Set(),
  );

  // ── Sort state (uncontrolled; props override when present) ───────────────
  const [localSortKey, setLocalSortKey] = useState<string | undefined>(
    sortKeyProp,
  );
  const [localSortAsc, setLocalSortAsc] = useState<boolean>(
    sortAscendingProp ?? true,
  );
  const activeSortKey = sortKeyProp !== undefined ? sortKeyProp : localSortKey;
  const activeSortAsc =
    sortAscendingProp !== undefined ? sortAscendingProp : localSortAsc;

  // ── Pagination state (uncontrolled; props override when present) ─────────
  const [localPage, setLocalPage] = useState<number>(currentPageProp ?? 0);
  const activePage =
    currentPageProp !== undefined ? currentPageProp : localPage;

  // ── Derived flags ────────────────────────────────────────────────────────
  const hasDetailRows = rows.some((row) => row.detailCard != null);
  // Total column count used for detail-row colSpan
  const colCount = columns.length + (hasDetailRows ? 1 : 0);

  // ── Sorted rows ──────────────────────────────────────────────────────────
  const sortedRows = useMemo(() => {
    if (!activeSortKey) return rows;
    return [...rows].sort((a, b) => {
      const av = (a.data as Record<string, unknown>)[activeSortKey];
      const bv = (b.data as Record<string, unknown>)[activeSortKey];
      if (av == null && bv == null) return 0;
      if (av == null) return 1;
      if (bv == null) return -1;
      const cmp = av < bv ? -1 : av > bv ? 1 : 0;
      return activeSortAsc ? cmp : -cmp;
    });
  }, [rows, activeSortKey, activeSortAsc]);

  // ── Paginated slice ──────────────────────────────────────────────────────
  const paginatedRows = useMemo(() => {
    if (!pageSize) return sortedRows;
    const start = activePage * pageSize;
    return sortedRows.slice(start, start + pageSize);
  }, [sortedRows, pageSize, activePage]);

  const totalPages = pageSize ? Math.ceil(sortedRows.length / pageSize) : 1;

  // ── Handlers ─────────────────────────────────────────────────────────────
  const handleSortClick = (key: string) => {
    const newAsc = activeSortKey === key ? !activeSortAsc : true;
    setLocalSortKey(key);
    setLocalSortAsc(newAsc);
    onSortChanged({key, ascending: newAsc});
  };

  const handleToggleDetail = (row: DataTableRowType, e: React.MouseEvent) => {
    e.stopPropagation();
    setExpandedRows((prev) => {
      const next = new Set(prev);
      if (next.has(row.id)) {
        next.delete(row.id);
        onHideDetail({rowId: row.id, row});
      } else {
        next.add(row.id);
        onShowDetail({rowId: row.id, row});
      }
      return next;
    });
  };

  const handleRowClick = (row: DataTableRowType) => {
    onRowClicked({rowId: row.id, row});
  };

  const handlePageChange = (page: number) => {
    setLocalPage(page);
    if (pageSize) {
      onPageChanged({page, pageSize});
    }
  };

  // ── Cell padding ─────────────────────────────────────────────────────────
  const cellPad = compact ? "py-1 px-2" : "py-2 px-3";

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <div className={cn("w-full", className)} data-pihanga={cardName}>
      <Table>
        {caption && <TableCaption>{caption}</TableCaption>}

        {/* ── Header ─────────────────────────────────────────────────────── */}
        <TableHeader
          className={
            stickyHeader ? "sticky top-0 z-10 bg-background" : undefined
          }
        >
          <TableRow>
            {/* Expand-toggle placeholder header cell */}
            {hasDetailRows && (
              <TableHead className="w-10 px-2" aria-label="Row details" />
            )}

            {columns.map((col) => (
              <TableHead
                key={col.key}
                style={col.width ? {width: col.width} : undefined}
                className={cn(
                  cellPad,
                  col.align === "center" && "text-center",
                  col.align === "right" && "text-right",
                  col.sortable && "cursor-pointer select-none",
                  col.headerClassName,
                )}
                onClick={
                  col.sortable ? () => handleSortClick(col.key) : undefined
                }
              >
                <span className="inline-flex items-center">
                  {col.title ?? keyToTitle(col.key)}
                  {col.sortable && (
                    <SortIcon
                      columnKey={col.key}
                      activeKey={activeSortKey}
                      ascending={activeSortAsc}
                    />
                  )}
                </span>
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>

        {/* ── Body ───────────────────────────────────────────────────────── */}
        <TableBody>
          {paginatedRows.length === 0 ? (
            /* Empty state */
            <TableRow>
              <TableCell
                colSpan={colCount}
                className="py-8 text-center text-muted-foreground"
              >
                {emptyCard ? (
                  <Card cardName={emptyCard} parentCard={cardName} />
                ) : (
                  emptyText
                )}
              </TableCell>
            </TableRow>
          ) : (
            paginatedRows.map((row, rowIdx) => {
              const isExpanded = expandedRows.has(row.id);
              const isStriped = striped && rowIdx % 2 === 1;

              return (
                <React.Fragment key={row.id}>
                  {/* ── Data row ─────────────────────────────────────────── */}
                  <TableRow
                    className={cn(
                      isStriped && "bg-muted/30",
                      hoverable && "cursor-pointer",
                    )}
                    data-expanded={isExpanded || undefined}
                    onClick={() => handleRowClick(row)}
                  >
                    {/* Expand / collapse toggle */}
                    {hasDetailRows && (
                      <TableCell className="w-10 px-2">
                        {row.detailCard && (
                          <button
                            type="button"
                            aria-label={
                              isExpanded ? "Collapse detail" : "Expand detail"
                            }
                            aria-expanded={isExpanded}
                            className={cn(
                              "flex items-center justify-center rounded p-0.5 transition-colors",
                              "hover:bg-accent focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                            )}
                            onClick={(e) => handleToggleDetail(row, e)}
                          >
                            {isExpanded ? (
                              <ChevronDown className="size-4" />
                            ) : (
                              <ChevronRight className="size-4" />
                            )}
                          </button>
                        )}
                      </TableCell>
                    )}

                    {/* Data cells */}
                    {columns.map((col) => {
                      const value = (row.data as Record<string, unknown>)[
                        col.key
                      ];
                      return (
                        <TableCell
                          key={col.key}
                          className={cn(
                            cellPad,
                            col.align === "center" && "text-center",
                            col.align === "right" && "text-right",
                            col.cellClassName,
                          )}
                        >
                          {renderCell(col, value, cardName)}
                        </TableCell>
                      );
                    })}
                  </TableRow>

                  {/* ── Detail row (full-width, shown when expanded) ──────── */}
                  {isExpanded && row.detailCard && (
                    <TableRow
                      // Suppress the default hover/click styles on the detail row
                      className="hover:bg-transparent"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <TableCell colSpan={colCount} className="border-b p-0">
                        <div className="bg-muted/20 px-4 py-3">
                          {/*
                           * cardKey creates a unique virtual card instance per row
                           * (e.g. "myDetailTemplate@detail-42").
                           * The `row` prop is forwarded as ctxtProps so the detail
                           * card's state-mapper functions can access it via
                           * `ctx.ctxtProps.row` — no need to pre-register one card
                           * per row.
                           */}
                          <Card
                            cardName={row.detailCard}
                            cardKey={`detail-${row.id}`}
                            row={row}
                            parentCard={cardName}
                            key={`${cardName}-${row.id}-detail`}
                          />
                        </div>
                      </TableCell>
                    </TableRow>
                  )}
                </React.Fragment>
              );
            })
          )}
        </TableBody>
      </Table>

      {/* ── Pagination controls ──────────────────────────────────────────── */}
      {pageSize && totalPages > 1 && (
        <PaginationBar
          page={activePage}
          totalPages={totalPages}
          onPrev={() => handlePageChange(activePage - 1)}
          onNext={() => handlePageChange(activePage + 1)}
        />
      )}
    </div>
  );
};

import {
  PiCardRef,
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const DATA_TABLE_CARD = "shad/data-table";

export const DataTable = createCardDeclaration<DataTableProps, DataTableEvents>(
  DATA_TABLE_CARD,
);

export const DATA_TABLE_ACTION = registerActions(DATA_TABLE_CARD, [
  "row_clicked",
  "sort_changed",
  "show_detail",
  "hide_detail",
  "page_changed",
]);

export const onDataTableRowClicked = createOnAction<DataTableRowClickedEvent>(
  DATA_TABLE_ACTION.ROW_CLICKED,
);
export const onDataTableSortChanged = createOnAction<DataTableSortChangedEvent>(
  DATA_TABLE_ACTION.SORT_CHANGED,
);
export const onDataTableShowDetail = createOnAction<DataTableDetailEvent>(
  DATA_TABLE_ACTION.SHOW_DETAIL,
);
export const onDataTableHideDetail = createOnAction<DataTableDetailEvent>(
  DATA_TABLE_ACTION.HIDE_DETAIL,
);
export const onDataTablePageChanged = createOnAction<DataTablePageChangedEvent>(
  DATA_TABLE_ACTION.PAGE_CHANGED,
);

// ---------------------------------------------------------------------------
// Column type definitions
// ---------------------------------------------------------------------------

/** Shared base for all column definitions */
export type DataTableColumnBase = {
  /** Key into the row's `data` object used to retrieve the cell value */
  key: string;
  /**
   * Column header label.
   * Defaults to the `key` with camelCase expanded to "Title Case".
   */
  title?: string;
  /** Column width as a CSS value (e.g. "120px", "10%", "1fr") */
  width?: string | number;
  /** Horizontal alignment of cell content. Defaults to "left". */
  align?: "left" | "center" | "right";
  /** Whether the column header is clickable for sorting */
  sortable?: boolean;
  /** Extra CSS class applied to the `<th>` header cell */
  headerClassName?: string;
  /** Extra CSS class applied to every `<td>` data cell in this column */
  cellClassName?: string;
};

/** Plain text column — cell value rendered as a string */
export type TextColumn = DataTableColumnBase & {
  type?: "text";
};

/** Numeric column with optional custom formatter */
export type NumberColumn = DataTableColumnBase & {
  type: "number";
  /** Custom number formatter; defaults to `String(value)` */
  format?: (n: number) => string;
};

/** Badge/chip column — cell value is rendered inside a `<Badge>` */
export type BadgeColumn = DataTableColumnBase & {
  type: "badge";
  /**
   * Map from cell value (as a string) to a shadcn Badge variant.
   * Falls back to "secondary" for unrecognised values.
   */
  variants?: Record<
    string,
    "default" | "secondary" | "destructive" | "outline"
  >;
};

/** Date column with optional custom formatter */
export type DateColumn = DataTableColumnBase & {
  type: "date";
  /** Custom date formatter; defaults to `toLocaleDateString()` */
  format?: (d: Date | string) => string;
};

/** Boolean column — renders a check-mark or cross icon */
export type BooleanColumn = DataTableColumnBase & {
  type: "boolean";
};

/**
 * Card column — cell value must be a `PiCardRef` (string).
 * The referenced card is rendered inline via Pihanga's `<Card />`.
 * This enables full reuse of any registered Pihanga card as cell content.
 */
export type CardColumn = DataTableColumnBase & {
  type: "card";
};

export type DataTableColumn =
  | TextColumn
  | NumberColumn
  | BadgeColumn
  | DateColumn
  | BooleanColumn
  | CardColumn;

// ---------------------------------------------------------------------------
// Row
// ---------------------------------------------------------------------------

export type DataTableRow<T = Record<string, unknown>> = {
  /** Unique row identifier used as the React key and in events */
  id: string | number;
  /**
   * Row payload — values are keyed by the column's `key` field.
   * For "card" columns the value should be a `PiCardRef` string.
   */
  data: T;
  /**
   * When set, the row shows an expand/collapse toggle button.
   * The referenced card is rendered full-width below the row on expand.
   * Use `onShowDetail` / `onHideDetail` events to track expanded state in
   * your redux store and update `detailCard` per row as needed.
   */
  detailCard?: PiCardRef;
};

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

export type DataTableProps<T = Record<string, unknown>> = {
  /** Column definitions — order determines display order */
  columns: DataTableColumn[];
  /** Row data */
  rows: DataTableRow<T>[];
  /** Optional visible `<caption>` rendered below the table */
  caption?: string;

  // --- Sorting ---
  /**
   * Key of the currently sorted column.
   * When provided the sort state is controlled; otherwise managed internally.
   */
  sortKey?: string;
  /**
   * Sort direction.
   * When provided together with `sortKey` the sort state is controlled.
   */
  sortAscending?: boolean;

  // --- Pagination ---
  /** Maximum number of rows per page. Omit to disable pagination. */
  pageSize?: number;
  /** Current page index (0-based). Treated as controlled when provided. */
  currentPage?: number;
  /**
   * Total row count, used for server-side pagination display.
   * Leave unset for client-side pagination derived from `rows.length`.
   */
  totalRows?: number;

  // --- Display ---
  /** Keep the header visible while the body scrolls */
  stickyHeader?: boolean;
  /** Alternate row background colour (zebra striping) */
  striped?: boolean;
  /** Highlight rows on hover (default: true) */
  hoverable?: boolean;
  /** Use compact row padding */
  compact?: boolean;

  // --- Empty state ---
  /** Card rendered when `rows` is empty */
  emptyCard?: PiCardRef;
  /** Fallback text when `rows` is empty and `emptyCard` is not set */
  emptyText?: string;

  className?: string;
};

// ---------------------------------------------------------------------------
// Events
// ---------------------------------------------------------------------------

export type DataTableRowClickedEvent = {
  rowId: string | number;
  row: DataTableRow;
};

export type DataTableSortChangedEvent = {
  /** The column key that was clicked */
  key: string;
  /** `true` = ascending, `false` = descending */
  ascending: boolean;
};

export type DataTableDetailEvent = {
  rowId: string | number;
  row: DataTableRow;
};

export type DataTablePageChangedEvent = {
  /** New page index (0-based) */
  page: number;
  pageSize: number;
};

export type DataTableEvents = {
  onRowClicked: DataTableRowClickedEvent;
  onSortChanged: DataTableSortChangedEvent;
  onShowDetail: DataTableDetailEvent;
  onHideDetail: DataTableDetailEvent;
  onPageChanged: DataTablePageChangedEvent;
};

// ---------------------------------------------------------------------------
// DataTableRowDetail — generic single-template detail panel
// ---------------------------------------------------------------------------

/** Configuration for a single field shown in the detail panel. */
export type DataTableRowDetailField = {
  /** Key to look up in `row.data` */
  key: string;
  /** Optional human-readable label prefix (e.g. "Director") */
  label?: string;
  /** Render style: "title" → h4 bold, "muted" → muted foreground, "text" (default) → plain */
  type?: "title" | "text" | "muted";
  /** Additional Tailwind class names forwarded to the element */
  className?: string;
};

export type DataTableRowDetailProps = {
  /**
   * The row to display. Set this via a state mapper so a single template
   * card works for all rows:
   * ```ts
   * DataTableRowDetail({
   *   row: (_, ctx) => ctx.ctxtProps?.row,
   *   fields: [{ key: "title", type: "title" }, ...],
   * })
   * ```
   */
  row?: DataTableRow<Record<string, unknown>>;
  /**
   * Fields to render in order.
   * When omitted, every key in `row.data` is rendered as a plain key:value pair.
   */
  fields?: DataTableRowDetailField[];
};

export const DATA_TABLE_ROW_DETAIL_CARD = "shad/data-table-row-detail";
export const DataTableRowDetail =
  createCardDeclaration<DataTableRowDetailProps>(DATA_TABLE_ROW_DETAIL_CARD);

import React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {cn} from "@/lib/utils";
import type {
  DataTableRowDetailField,
  DataTableRowDetailProps,
} from "./dataTable.types";

/**
 * DataTableRowDetail — generic detail-panel card for use with DataTable.
 *
 * Register it ONCE as a template, then reference it in every row via
 * `detailCard`.  The DataTable passes the row via `cardKey` + `row` context
 * props so a state mapper on the `row` field delivers the correct data:
 *
 * ```ts
 * registerCard(
 *   "app/myTable/rowDetail",
 *   DataTableRowDetail({
 *     // State mapper — ctx.ctxtProps.row is injected by the DataTable
 *     row: (_, ctx) => ctx.ctxtProps?.row,
 *     fields: [
 *       { key: "title",    type: "title" },
 *       { key: "director", label: "Director" },
 *       { key: "plot",     type: "muted" },
 *     ],
 *   }),
 * );
 * ```
 */
export const DataTableRowDetailComponent = (
  props: PiCardProps<DataTableRowDetailProps>,
): React.ReactNode => {
  const {row, fields, cardName} = props;

  if (!row?.data) {
    return null;
  }

  const data = row.data as Record<string, unknown>;

  /** If no `fields` config, auto-render all keys as plain text */
  if (!fields || fields.length === 0) {
    return (
      <div className="flex flex-col gap-1 text-sm" data-pihanga={cardName}>
        {Object.entries(data).map(([key, value]) => (
          <div key={key}>
            <span className="font-medium text-muted-foreground">{key}: </span>
            <span>{String(value ?? "")}</span>
          </div>
        ))}
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-1" data-pihanga={cardName}>
      {fields.map((field: DataTableRowDetailField) => {
        const value = data[field.key];
        const display = value == null ? "" : String(value);

        switch (field.type) {
          case "title":
            return (
              <h4 key={field.key} className="text-base font-semibold">
                {display}
              </h4>
            );

          case "muted":
            return (
              <p key={field.key} className="text-sm text-muted-foreground">
                {field.label ? (
                  <>
                    <span className="font-medium">{field.label}: </span>
                    {display}
                  </>
                ) : (
                  display
                )}
              </p>
            );

          default:
            // "text" or any unknown type
            return (
              <p key={field.key} className={cn("text-sm", field.className)}>
                {field.label ? (
                  <>
                    <span className="font-medium">{field.label}: </span>
                    {display}
                  </>
                ) : (
                  display
                )}
              </p>
            );
        }
      })}
    </div>
  );
};

import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {DataTableComponent} from "./dataTable.component";
import {DataTableRowDetailComponent} from "./dataTableRowDetail.component";
import {
  DATA_TABLE_ACTION,
  DATA_TABLE_CARD,
  DATA_TABLE_ROW_DETAIL_CARD,
} from "./dataTable.types";

export * from "./dataTable.types";

registerCardComponent({
  name: DATA_TABLE_CARD,
  component: DataTableComponent,
  events: actionTypesToEvents(DATA_TABLE_ACTION),
});

registerCardComponent({
  name: DATA_TABLE_ROW_DETAIL_CARD,
  component: DataTableRowDetailComponent,
});
